package main
import("encoding/json";"go/scanner";"go/token";"os";"reflect";"strings";"fmt")
func tokens(s string, normalize bool) []string { var sc scanner.Scanner;fs:=token.NewFileSet();sc.Init(fs.AddFile("input.go",fs.Base(),len(s)),[]byte(s),nil,0);out:=[]string{};for {_,t,l:=sc.Scan();if t==token.EOF{break};if t==token.SEMICOLON{continue};if normalize&&t==token.STRING{l="<string>"};out=append(out,t.String()+":"+l)};return out }
func main(){raw,e:=os.ReadFile("../server-final-evidence/baseline.json");if e!=nil{panic(e)};var base map[string]string;json.Unmarshal(raw,&base);results:=map[string]bool{};for p,b:=range base{if strings.HasSuffix(p,"_test.go"){continue};a,e:=os.ReadFile(p);if e!=nil{panic(e)};results[p]=reflect.DeepEqual(tokens(b,true),tokens(string(a),true))};b,_:=json.MarshalIndent(results,"","  ");os.WriteFile("../server-final-evidence/token-structure-check.json",b,0600);bad:=0;for p,ok:=range results{if !ok {fmt.Println("STRUCTURAL CHANGE",p);bad++}};fmt.Printf("Checked %d production Go files; non-string/comment structural differences: %d\n",len(results),bad);if bad>0{os.Exit(1)}}
